"""Input validation helpers."""


def parse_age(value):
    """Parse an age string into an int."""
    try:
        age = int(value)
    except ValueError:
        raise ValueError("Invalid age input. Please enter a valid integer.")

    if age < 0:
        raise ValueError("Age cannot be negative.")
    if age > 150:
        raise ValueError("Age cannot exceed 150.")

    return age
